mapper.select:
SELECT * FROM appointment_slot

    deleted = 0

        AND package_id = #{packageId}


        AND appoint_date = #{appointDate}


        AND status = #{status}


ORDER BY appoint_date ASC, time_range ASC

mapper.update:
UPDATE appointment_slot
SET current_count = current_count - 1
WHERE id = #{id}

mapper.select:
SELECT price FROM appointment_package p
JOIN appointment_slot s ON p.id = s.package_id
WHERE s.id = #{slotId}
